{
  "summary": "Gather current warehousing contract terms, renewal/pricing policy, SLA performance data, and outstanding invoices, then draft a reply to Globex Logistics addressing the proposed 5% increase and renewal from 1 December 2026.",
  "reply_type": "vendor_email",
  "steps": [
    {
      "id": 1,
      "agent": "retriever",
      "task": "List and read the current Globex Logistics warehousing contract (terms, pricing, expiry, renewal clauses), any pricing/escalation policy documents governing rate increases, recent SLA performance records for Globex Logistics, and outstanding invoices or credits owed; use the SLA credit calculator to determine any exact SLA misses and credits owed to Globex Logistics.",
      "why": "All facts needed for a complete, accurate response—contract terms, policy on increases, SLA performance, and financial obligations—must be gathered before drafting the reply."
    },
    {
      "id": 2,
      "agent": "executor",
      "task": "Draft the reply email to Globex Logistics confirming or countering the 5% increase renewal from 1 December 2026, referencing current contract terms, applicable pricing policy, SLA performance, and any credits owed, for human review and approval.",
      "why": "The executor synthesizes the gathered facts into the final vendor-facing response for approval."
    }
  ],
  "escalate": null
}
